<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { object, rows, text, type Body } from '../../../shared/contracts.ts';
import { copyText, phoneHref } from '../platform.ts';

const props=defineProps<{section:'home'|'catalog'|'cases'|'contact'|'directory'; body:Body}>();
const tracker=ref<HTMLElement|null>(null),index=ref(0),held=ref(false),reading=ref(false),hidden=ref(false),failed=ref<string[]>([]);
const posters=computed(()=> (Array.isArray(props.body.poster_asset_urls)?props.body.poster_asset_urls:[]).filter((src):src is string=>typeof src==='string'&&!failed.value.includes(src)));
const reduced=ref(false);let timer:ReturnType<typeof setInterval>|undefined;
function scrollSlide(to:number){const el=tracker.value;if(!el||!el.clientWidth)return;index.value=to;el.scrollTo({left:to*el.clientWidth,behavior:reduced.value?'instant':'smooth'});reading.value=(el.children[to]?.scrollTop??0)>2;}
function scrolled(){const el=tracker.value;if(!el||!el.clientWidth)return;index.value=Math.round(el.scrollLeft/el.clientWidth);reading.value=(el.children[index.value]?.scrollTop??0)>2;}
function drop(src:string){if(!failed.value.includes(src))failed.value=[...failed.value,src];void nextTick(()=>scrollSlide(Math.min(index.value,Math.max(0,posters.value.length-1))));}
function release(){held.value=false;}
function visibility(){hidden.value=document.hidden;}
function schedule(){clearInterval(timer);if(props.section==='home'&&posters.value.length>1&&!held.value&&!reading.value&&!hidden.value&&!reduced.value){timer=setInterval(()=>scrollSlide((index.value+1)%posters.value.length),4000);}}
watch([()=>posters.value.length,held,reading,hidden,reduced],schedule);
watch(()=>props.body,()=>{failed.value=[];index.value=0;reading.value=false;});
const services=computed(()=>object(props.body.services)), contact=computed(()=>object(props.body.business_contact));
const cards=computed(()=>rows(services.value.cards));
const tones=['blue','silver','mint'] as const;
const dialog=ref<'contact'|'image'|'card'|null>(null), zoom=ref(''), previewIndex=ref(-1), fallback=ref(''),notice=ref('');
let trigger:HTMLElement|null=null;
function lines(value:unknown){return text(value).split(/\n/).map(line=>line.trim()).filter(Boolean);}
function open(kind:'contact'|'image'|'card',image=''){trigger=document.activeElement as HTMLElement;dialog.value=kind;zoom.value=image;fallback.value='';void nextTick(()=>document.querySelector<HTMLButtonElement>('.h5-overlay .dialog-close')?.focus());}
function openCard(index:number){const card=cards.value[index];if(card?.image_asset_url){previewIndex.value=-1;open('image',text(card.image_asset_url));return;}previewIndex.value=index;open('card');}
function close(){dialog.value=null;zoom.value='';previewIndex.value=-1;fallback.value='';trigger?.focus();}
function keys(event:KeyboardEvent){if(event.key==='Escape'&&dialog.value)close();}
async function copy(value:string){if(await copyText(value))notice.value='已复制微信号';else fallback.value=value;}
onMounted(()=>{hidden.value=document.hidden;reduced.value=window.matchMedia('(prefers-reduced-motion: reduce)').matches;document.addEventListener('visibilitychange',visibility);window.addEventListener('pointerup',release);window.addEventListener('pointercancel',release);window.addEventListener('keydown',keys);schedule();});
onBeforeUnmount(()=>{clearInterval(timer);document.removeEventListener('visibilitychange',visibility);window.removeEventListener('pointerup',release);window.removeEventListener('pointercancel',release);window.removeEventListener('keydown',keys);});
</script>
<template>
 <section v-if="section==='home'" class="company-page" aria-label="首页">
   <div v-if="posters.length" ref="tracker" class="poster-track" role="region" aria-label="首页长图轮播" @scroll="scrolled" @pointerdown="held=true" @focusin="held=true" @focusout="release">
     <article v-for="(src,i) in posters" :key="`${src}:${i}`" class="poster-slide" @scroll="i===index && (reading=($event.currentTarget as HTMLElement).scrollTop>2)"><img :src="src" :alt="`企业产品海报，第 ${i+1} 张`" draggable="false" decoding="async" @error="drop(src)"></article>
   </div>
   <p v-else class="h5-empty">暂无展示海报</p><nav v-if="posters.length>1" class="poster-dots" aria-label="海报翻页"><component :is="'button'" v-for="(_,i) in posters" :key="i" :aria-label="`查看第 ${i+1} 张海报`" :aria-current="i===index?'true':undefined" type="button" @click="scrollSlide(i)"></component></nav>
 </section>
 <div v-else-if="section==='catalog' && (body.cover_asset_url||body.slogan_top||body.slogan_bottom)" class="catalog-cover"><img v-if="body.cover_asset_url" :src="text(body.cover_asset_url)" alt="产品目录封面"><div v-if="!body.image_has_text" class="catalog-cover-copy"><p>{{text(body.slogan_top)}}</p><strong>{{text(body.slogan_bottom)}}</strong></div></div>
 <header v-else-if="section==='cases'" class="cases-hero"><img v-if="body.background_asset_url" :src="text(body.background_asset_url)" alt=""><div><h1>{{text(body.title,'品牌案例')}}</h1><p v-if="body.intro">{{text(body.intro)}}</p></div></header>
 <section v-else-if="section==='directory'" class="directory-preview"><h2>产品目录</h2><p v-if="!rows(body.nodes).length" class="h5-empty">暂无目录</p><div v-for="node in rows(body.nodes)" :key="text(node.id)" :style="{paddingLeft:node.level==='board'?'0':node.level==='category'?'16px':'32px'}"><strong>{{text(node.name,'未命名')}}</strong><small v-if="node.enabled===false"> · 已停用</small></div></section>
 <section v-else-if="section==='contact'" class="contact-page"><header class="contact-header"><div class="contact-header-copy"><h1>{{text(services.page_title,'服务与合作')}}</h1><p v-if="services.intro">{{text(services.intro)}}</p></div><component :is="'button'" class="contact-consult" type="button" @click="open('contact')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 12a8 8 0 0 1-8 8H7l-4 3V12a8 8 0 1 1 18 0z"/></svg><span>{{text(services.consult_label,'合作咨询')}}</span></component></header>
  <div class="contact-content"><div class="contact-section-head"><h2>{{text(services.section_title,'我们能为你做什么')}}</h2><span v-if="services.sample_label" class="contact-sample">{{text(services.sample_label)}}</span></div>
  <div v-if="cards.length" class="contact-service-list"><article v-for="(card,i) in cards" :key="i" class="contact-service"><component :is="'button'" type="button" @click="openCard(i)"><img v-if="card.image_asset_url" class="contact-service-photo" :src="text(card.image_asset_url)" :alt="text(card.title,'服务图片')" loading="lazy"><div v-else class="contact-service-art" :data-tone="tones[i%3]"><div class="contact-service-copy"><span v-if="card.eyebrow" class="contact-service-label">{{text(card.eyebrow)}}</span><p class="contact-service-headline"><span v-for="(line,n) in lines(card.headline||card.title)" :key="n">{{line}}</span></p><p v-if="lines(card.points||card.description).length" class="contact-service-summary"><span v-for="(line,n) in lines(card.points||card.description)" :key="n">{{line}}</span></p></div><div class="contact-service-visual" aria-hidden="true"><svg v-if="i%3===0" viewBox="0 0 24 24"><path d="M10 2v6L6 16a4 4 0 0 0 4 6h4a4 4 0 0 0 4-6l-4-8V2"/><path d="M8.5 2h7"/><path d="M7 15h10"/></svg><svg v-else-if="i%3===1" viewBox="0 0 24 24"><path d="M12 3 4 7v10l8 4 8-4V7z"/><path d="m4 7 8 4 8-4"/><path d="M12 11v10"/><path d="m9 14 3 2 3-2"/></svg><svg v-else viewBox="0 0 24 24"><path d="m12 2 9 5-9 5L3 7z"/><path d="m3 12 9 5 9-5"/><path d="m3 17 9 5 9-5"/></svg></div></div><span class="contact-service-caption"><span>{{text(card.title)}}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 3h6v6"/><path d="m21 3-7 7"/><path d="M9 21H3v-6"/><path d="m3 21 7-7"/></svg></span></component></article></div><p v-else class="h5-empty">暂无服务卡片</p>
  <section class="contact-business"><h2>{{text(contact.title,'商务联系')}}</h2><p v-if="contact.intro">{{text(contact.intro)}}</p><div class="contact-business-card"><img v-if="contact.qr_asset_url" class="contact-qr-image" :src="text(contact.qr_asset_url)" alt="商务联系二维码"><div v-else class="contact-qr-placeholder"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4z"/><path d="M14 14h2v2h-2zM18 14h2v2h-2zM14 18h2v2h-2zM18 18h2v2h-2z"/></svg><span>企业微信</span></div><div class="contact-business-copy"><h3>{{text(contact.label,'商务合作')}}</h3><p>{{text(contact.method,'扫码添加企业微信')}}</p><p v-if="contact.description">{{text(contact.description)}}</p><component :is="'button'" type="button" class="contact-link" @click="open('contact')">查看联系方式</component></div></div><p v-if="contact.note" class="contact-note">{{text(contact.note)}}</p></section></div>
  <div v-if="dialog" class="h5-overlay" role="dialog" aria-modal="true" :aria-label="dialog==='image'?'图片预览':dialog==='card'?'服务内容':'商务联系'" @click.self="close"><section class="h5-dialog"><div class="h5-section-head"><h2>{{dialog==='image'?'图片预览':dialog==='card'?text(cards[previewIndex]?.title,'服务内容'):text(contact.title,'商务联系')}}</h2><component :is="'button'" type="button" class="mobile-icon dialog-close" aria-label="关闭弹层" @click="close">×</component></div>
  <img v-if="dialog==='image'" :src="zoom" alt="放大的服务图片" class="zoom-image"><div v-else-if="dialog==='card'&&cards[previewIndex]" class="contact-service-preview"><div class="contact-service-art" :data-tone="tones[previewIndex%3]"><div class="contact-service-copy"><span v-if="cards[previewIndex].eyebrow" class="contact-service-label">{{text(cards[previewIndex].eyebrow)}}</span><p class="contact-service-headline"><span v-for="(line,n) in lines(cards[previewIndex].headline||cards[previewIndex].title)" :key="n">{{line}}</span></p><p v-if="lines(cards[previewIndex].points||cards[previewIndex].description).length" class="contact-service-summary"><span v-for="(line,n) in lines(cards[previewIndex].points||cards[previewIndex].description)" :key="n">{{line}}</span></p></div></div></div><template v-else><img v-if="contact.qr_asset_url" class="qr-image" :src="text(contact.qr_asset_url)" alt="长按保存商务二维码"><div v-else class="contact-qr-placeholder contact-qr-large"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4z"/><path d="M14 14h2v2h-2zM18 14h2v2h-2zM14 18h2v2h-2zM18 18h2v2h-2z"/></svg><span>企业微信</span></div><a v-if="contact.qr_asset_url" class="h5-soft" :href="text(contact.qr_asset_url)" download="contact-code">保存二维码</a><p v-if="contact.method">{{text(contact.method)}}</p><p v-if="contact.description">{{text(contact.description)}}</p><p v-if="contact.wechat_id">微信号：{{text(contact.wechat_id)}} <component :is="'button'" type="button" class="h5-soft" @click="copy(text(contact.wechat_id))">复制</component></p><p v-if="contact.phone">电话：<a :href="phoneHref(text(contact.phone))">{{text(contact.phone)}}</a></p><p v-if="contact.email">邮箱：<a :href="`mailto:${text(contact.email)}`">{{text(contact.email)}}</a></p><p v-if="contact.note" class="contact-note">{{text(contact.note)}}</p><input v-if="fallback" :value="fallback" readonly aria-label="手动复制微信号"><p v-if="notice" role="status">{{notice}}</p></template></section></div>
 </section>
</template>
